import React from "react";
import SearchBar, { Title, InputAndButton } from "./searchBar";
import "./searchBar.css";
import "bootstrap/dist/css/bootstrap.css";
import { override } from "prompts";

class Result extends SearchBar {
  constructor(props) {
    super();
    console.log(this.props.history);
    this.handleSubmitButtonOnClick = this.handleSubmitButtonOnClick.bind(this);
  }

  handleSubmitButtonOnClick(event) {
    // 禁止默认情况下按钮自动刷新整个页面
    event.preventDefault();
    alert("success");
  }

  render() {
    return (
      <div>
        <div id="search-title-revised">
          <Title />
          <InputAndButton handleSubmitButtonOnClick={this.handleSubmitButtonOnClick}/>
        </div>
      </div>
    );
  }
}

class SearchResult extends React.Component {
  render() {
    return (
      <div>
        <Result {...this.props} />
      </div>
    );
  }
}

export default SearchResult;
